/**
 * Return one page of the apps a Bot was given, each as it stands for the person asking: ready to use, waiting on their own account, waiting on an administrator, or turned off, with the next step and whose it is. An app removed after its actions were given is listed as turned off. Anybody who can use the Bot may list them. Apps come in order of their title, and by id among apps with the same title. A missing cursor starts at the first page and nextCursor null ends the list.
 * @summary List a Bot's apps
 */

export const listBotAppsPathBotIdRegExp = new RegExp("\\S");

export const ListBotAppsParams = zod.object({
  organizationId: zod
    .string()
    .min(1)
    .describe(
      "The organization, by its id or its slug. One the caller is not a member of answers as one that does not exist, `default` included.",
    ),
  botId: zod
    .string()
    .min(1)
    .regex(listBotAppsPathBotIdRegExp)
    .describe("The Bot's id."),
});

export const listBotAppsQueryLimitDefault = 50;
export const listBotAppsQueryLimitMax = 100;

export const listBotAppsQueryCursorMax = 4096;

export const listBotAppsQueryCursorRegExp = new RegExp("^[A-Za-z0-9_-]+$");

export const ListBotAppsQueryParams = zod.object({
  limit: zod
    .int()
    .min(1)
    .max(listBotAppsQueryLimitMax)
    .default(listBotAppsQueryLimitDefault)
    .describe("Most items in one page."),
  cursor: zod
    .string()
    .min(1)
    .max(listBotAppsQueryCursorMax)
    .regex(listBotAppsQueryCursorRegExp)
    .optional()
    .describe(
      "Opaque continuation from the previous page's nextCursor, bound to the organization and the filters that made it. The server only ever issues cursors written in URL-safe base64 (letters, digits, - and _, no padding) and refuses anything else, so the pattern says so. A cursor that fits the pattern can still be refused: one this list never gave out, or one made for another organization or other filters.",
    ),
});

export const listBotAppsResponseNextCursorMax = 4096;

export const listBotAppsResponseNextCursorRegExp = new RegExp(
  "^[A-Za-z0-9_-]+$",
);

export const ListBotAppsResponse = zod.object({
  apps: zod
    .array(
      zod
        .object({
          id: zod
            .string()
            .min(1)
            .describe("The app's id, or the one turning it on would give it."),
          title: zod.string().describe("The app's own name, such as Gmail."),
          logo: zod.string().nullable(),
          source: zod
            .enum(["catalogue", "address", "directory"])
            .describe(
              "Where the app comes from: OpenBot's catalogue, a server added by its address, or the directory of apps OpenBot can add.",
            ),
          account: zod
            .enum(["personal", "shared", "deployment"])
            .describe(
              "Whose account the app's actions use: each person's own, one shared account an administrator connects, or no person's.",
            ),
          connect: zod
            .union([zod.enum(["oauth", "consent", "key"]), zod.null()])
            .describe(
              "How the person's account is connected: OpenBot's own sign-in, the directory's sign-in, a key, or nothing to connect.",
            ),
          state: zod
            .enum([
              "ready",
              "not_connected",
              "reconnect",
              "shared_not_connected",
              "shared_not_approved",
              "disabled",
              "not_granted",
              "owner_grantable",
            ])
            .describe(
              "ready: usable now. not_connected and reconnect: waiting on an account the person connects (see accountHolder). shared_not_connected: waiting on the shared account. shared_not_approved: an administrator hasn't approved who may use the shared account through this Bot. disabled: turned off (see unavailable). not_granted: the Bot wasn't given it. owner_grantable: the same, and the person may give it themselves.",
            ),
          unavailable: zod
            .union([
              zod.enum([
                "absent",
                "directory_unavailable",
                "scheme_unreadable",
                "oauth_client_missing",
                "token_missing",
              ]),
              zod.null(),
            ])
            .describe(
              "Why the app is turned off, when state is disabled: nobody turned it on, the directory isn't set up here, OpenBot can't read how it connects, or it is missing the OAuth client or the key an administrator adds. Null otherwise.",
            ),
          accountHolder: zod
            .union([zod.enum(["you", "owner"]), zod.null()])
            .describe(
              "Whose own account the actions use for this person: theirs, or on somebody else's shared Bot the owner's, which only the owner can reconnect. Null where no person's own account is used.",
            ),
          asksFirst: zod
            .boolean()
            .describe(
              "The first use on the person's own account through somebody else's shared Bot asks them first. state is still ready.",
            ),
          granted: zod
            .boolean()
            .describe("The Bot was given at least one of the app's actions."),
          ownerGrants: zod
            .enum(["any", "admin"])
            .describe(
              "Who may give the app to a Bot: any Bot's owner, or only an administrator.",
            ),
          givenByOwner: zod
            .boolean()
            .describe(
              "Everything the Bot has of the app was given by its owner, who may take it back.",
            ),
          needsConnect: zod
            .boolean()
            .describe(
              "When state is owner_grantable, giving the app starts with connecting the person's own account. False otherwise.",
            ),
          connectedAt: zod.iso
            .datetime({ offset: true })
            .nullable()
            .describe(
              "When the account the app uses for this person was connected, or null.",
            ),
          requestKind: zod
            .union([
              zod
                .enum(["enable", "grant", "connect_shared"])
                .describe(
                  "What an administrator is asked for: to turn the app on, to give it to the Bot, or to connect its shared account.",
                ),
              zod.null(),
            ])
            .describe(
              "What a request would ask an administrator for in this state (createAppAccessRequest), or null where the next step is the person's own.",
            ),
          pendingRequest: zod
            .union([
              zod.object({
                id: zod.string(),
                kind: zod
                  .enum(["enable", "grant", "connect_shared"])
                  .describe(
                    "What an administrator is asked for: to turn the app on, to give it to the Bot, or to connect its shared account.",
                  ),
                createdAt: zod.iso.datetime({ offset: true }),
              }),
              zod.null(),
            ])
            .describe(
              "The person's own waiting request of that kind, or null.",
            ),
        })
        .describe(
          "One app as it stands for the person asking, on one Bot. state is OpenBot's: a client draws it and never works it out from the other fields.",
        ),
    )
    .describe("By title, and by id among apps with the same title."),
  nextCursor: zod
    .string()
    .max(listBotAppsResponseNextCursorMax)
    .regex(listBotAppsResponseNextCursorRegExp)
    .nullable()
    .describe(
      "Pass as cursor for the next page. Null ends the list. Written in URL-safe base64, the only form the cursor parameter accepts.",
    ),
});

